  ('cofta-2025', 'COFTA', 2025, 'COFTA 2025', 'men', '2025-09-06', '2025-09-06', 'Shephalbury Park', 'Two groups of three playing a double round-robin over six rounds, then semi-finals and a final', 6, 15, '4b5ef0e2-895c-5466-a254-704f8e08396b', '98a9121a-bb83-5462-aebd-41fe0ce8fd67', 'Archangel Michael, Golders Green 0-1 Anba Abraam, Brighton', 'full', 'Coptic_Football_Tournament_Archive_2024-2026.pdf, Section 2', '{"competition_full":"Coptic Orthodox Football Tournament Association","competition_note":"St Mark, Kensington finished second in Group B but were disqualified after the group stage had concluded. Archangel Michael, Golders Green progressed to the knockout stage in their place.","known_gaps":["The final''s goalscorer is not displayed.","Group A Round 6 (St George 0-0 St Anthony): no events displayed.","Three Group B matches display goals without team attribution (B-R1, B-R3, B-R4).","Some event pages use shortened player names (Peter, Sebastian, Stefano); reproduced as displayed rather than inferred.","Source does not state a team for any yellow card."]}'::jsonb),
  ('costa-2025', 'COSTA', 2025, 'COSTA 2025', 'men', '2025-10-25', '2025-10-26', null, null, 8, null, '4b5ef0e2-895c-5466-a254-704f8e08396b', 'c6f72270-d9ee-53e7-90fb-83a890734bc9', 'Brighton 5-0 SMPK', 'minimal', 'Adam''s notes, no supporting document', '{"team_count_basis":"count of named entrants only; source did not state a total","final_orientation_note":"Home/away sides of the final are not stated in the source.","known_gaps":["Top scorer''s goal total not stated.","No group stage, standings, fixtures or match data.","No venue.","No other goalscorers or player data.","Team list may be incomplete; only entrants named in the notes are recorded."],"final":{"home":null,"away":null,"winner_score":5,"loser_score":0,"decided_by":"regulation","winner":"Brighton","loser":"SMPK"}}'::jsonb),
  ('conafa-2026', 'CONAFA', 2026, 'CONAFA 2026', 'men', '2026-03-21', '2026-03-22', 'Pitch A, Pitch B and Pitch C', 'Group A of seven over seven rounds and Group B of six over five rounds, then quarter-finals, semi-finals and a final', 13, 43, '4b5ef0e2-895c-5466-a254-704f8e08396b', '743e2246-6b55-5f58-8d23-35ce49b9e88b', 'Nottingham 1-1 Brighton (Brighton won the shootout 5-4)', 'full', 'Coptic_Football_Tournament_Archive_2024-2026.pdf, Section 3 (Tournify app export)', '{"losing_semi_finalists":["Rotherham","Hounslow"],"third_place_match":null,"third_place_note":"No third-place match appears in any supplied screenshot.","round_numbering_note":"Round numbering in the app is not chronological: some Round 1 fixtures were played on 22/03 while Round 2 fixtures were played on 21/03. Rounds are recorded exactly as displayed.","player_of_the_match_note":"Reproduced exactly as displayed. The app shows no team attribution on this screen, so none has been inferred. 32 awards across 27 players captured; the list may extend beyond the 27 entries.","tournament_stats":{"total_matches":43,"total_goals":93,"group_stage_goals":82,"knockout_goals":11,"goals_per_match":2.16,"recorded_goal_events":89,"goals_with_no_recorded_scorer":4,"yellow_cards":11,"red_cards":0,"own_goals":2,"penalty_shootouts":2,"biggest_win":"St Marks 7-0 Hove (Group A Round 3)","most_goals_in_one_match_by_a_player":"Stavros Akriviadis (St Marks) 3 v Hove, Group A Round 3","most_clean_sheets":"Brighton, 7 in 8 matches"},"known_gaps":["Six group matches show score only with no event data: A-R1-01, A-R1-02, A-R3-02, A-R4-02, A-R6-03, B-R2-02.","Four Group A goals therefore have no recorded scorer (3 in Nottingham 2-1 Birmingham, 1 in Hove 0-1 Newcastle).","A-R6-02 (Nottingham 1-0 Rotherham): scorer supplied by the organiser, not by a screenshot; minute unknown.","Date, kick-off and pitch are not displayed for QF1, QF3, QF4, SF1, SF2 and the Final. QF2 shows a date and time but no pitch.","Own goal at 86'' in St Marks 7-0 Hove has no player name.","Player of the Match leaderboard has no team attribution and may be incomplete.","No third-place match appears in any supplied screenshot.","Spelling variants Stavros Akriviadis / Stavros Arkiviadis retained separately, not merged.","''Antony Messag'' may be truncated in the app.","Self-credited assists preserved as displayed and not corrected."]}'::jsonb),
  ('cosa-2026', 'COSA', 2026, 'COSA 2026', 'women', '2026-06-20', '2026-06-20', null, 'Three-team league phase followed by a final', 3, 7, 'c6f72270-d9ee-53e7-90fb-83a890734bc9', '98a9121a-bb83-5462-aebd-41fe0ce8fd67', 'SMPK 5-0 Golders Green', 'full', 'Coptic_Football_Tournament_Archive_2024-2026.pdf, Section 4', '{"venue_note":"Venue not recorded in the source data.","league_table_note":"No league table appears in the source; standings are not reproduced here and must not be computed and presented as source data.","known_gaps":["Venue not recorded.","No league table supplied.","Game 1 assist sequence had three entries for four SMPK goals; fourth goal recorded with no assist.","No kick-off times, no cards and no minutes anywhere in the source.","WOTM published totals do not reconcile with the per-match awards (see wotm_conflict)."]}'::jsonb),
  ('ark-cup-2026', 'The Ark Cup', 2026, 'The Ark Cup 2026', 'men', '2026-06-27', '2026-06-28', 'Pitch 1 and Pitch 2', 'Six-team league phase, play-off, semi-finals and final', 6, 19, 'c6f72270-d9ee-53e7-90fb-83a890734bc9', '6a1101b5-5900-57fb-b71c-52e0813f7e75', 'Stevenage 0-0 SMPK (SMPK won the shootout 4-3)', 'full', 'Coptic_Football_Tournament_Archive_2024-2026.pdf, Section 5', '{"edition_note":"St Mary and Archangel Michael Church''s inaugural men''s football tournament.","league_table_note":"The source table shows GD and Pts only; no GF/GA columns were displayed. gf_derived/ga_derived were computed from the fixture list by the compiler and are NOT source data; they reconcile exactly to the published GD. Store them in a derived column or omit.","squads_note":"These are the players captured from event data only, not full squad lists.","known_gaps":["St Mary''s 1-3 St Mark''s: one St Mark''s goal has no recorded scorer.","Golders Green 3-0 St Mark''s: no goalscorers displayed.","Play-off Golders Green 2-0 St Mary''s: three goal events displayed against an official 2-0 score.","St Mark''s are shown 6th despite holding 3 points; the UI marks them with an exclusion/prohibition symbol.","No minutes are recorded for any event.","League table shows GD and Pts only; no GF/GA columns.","Published goalscorer leaderboard exceeds event-derived counts for three players (see goalscorer_reconciliation)."],"host_club":"Archangel Michael, Golders Green","teams_note":"''St Mary''s'' is Golders Green''s second team; both A and B teams of the host club competed.","goalscorer_reconciliation":{"note":"The published leaderboard exceeds the count derivable from the displayed match events for three players. Store the leaderboard as published AND store the event-derived count, flagged.","discrepancies":[{"player":"Daniel Samaan","published":5,"from_events":4},{"player":"Stavros Akriviadis","published":5,"from_events":4},{"player":"Robel Hailemichael","published":2,"from_events":1}],"likely_cause_unconfirmed":"The extra entries may be penalty shootout conversions from the Brighton v Stevenage semi-final, which the archive instructs should not count as goals. NOT CONFIRMED — do not resolve without sign-off."},"squads_named":{"Brighton":["Demas Ramsis","Abanob Fakhory","Peter Barkoci","Sebastian Chotuis","Stavros Akriviadis","Keyroulos Fakhory","Leon Lawandi","Alessio Saleh","Oukeen Asad","Girgis Asad","Martin Farkas"],"SMPK":["Natinael Genene","Naty Musie","Amanuel Tarkegn","Marcelino Aziz","Daniel Kyriacou","Andrew Ramzy"],"Stevenage":["Daniel Samaan","Robel Hailemichael","Jon Adorante","Abs Fidal","Karim Rizkallah","Sherif Rizkallah","John Fahmy","Decio Emmanuel","Abel Solomon","Mina Habib"],"Golders Green":["CJ Forbes","Isaac Boakye","Simon Fakhouri","Marino Rofail","Andrew Louis"],"St Mary''s":["Kaniel Bennett-Flaming","Jonathan Henein","Cameron Crumlin","Kero Daoud"],"St Mark''s":["Mark Ayoub","Kyro Fawzy Aziz","Chris Tamou"]}}'::jsonb);
