insert into public.archive_conflicts (id, scope, severity, issue, detail, resolution, status) values
  ('D1', 'ark-cup-2026', 'high', 'Published goalscorer leaderboard exceeds event-derived counts.', 'Daniel Samaan published 5 / events 4; Stavros Akriviadis published 5 / events 4; Robel Hailemichael published 2 / events 1. Possible cause: shootout conversions in the Brighton v Stevenage semi-final counted as goals in the app leaderboard. Unconfirmed.', 'Store both figures. Do not pick one. RESOLVED by Adam (Q5): the extra entries were shootout conversions, so the event-derived figures are canonical and the published leaderboard is inflated. Both remain stored.', 'resolved'),
  ('D2', 'ark-cup-2026', 'high', 'Play-off event count exceeds score.', 'Golders Green 2-0 St Mary''s shows three Golders Green goal events (Marino Rofail, CJ Forbes, Andrew Louis) against an official 2-0.', 'Preserve the official 2-0. Store all three events flagged.', 'open'),
  ('D3', 'cosa-2026', 'high', 'WOTM totals do not reconcile.', 'The published table gives Mariam Makkar 4 WOTM and totals 8 awards across 7 matches. Per-match records give Makkar 3 (Games 1, 2, Final).', 'Store per-match awards as primary; store the published table flagged.', 'open'),
  ('D4', 'cofta-2024', 'medium', 'Source''s own count of unattributed goals is wrong and self-contradictory.', 'The summary page says ''three goals have no displayed scorer''; the goalscorer table note says ''two goals are unassigned'' then describes four. Arithmetic against the fixtures gives 35 total goals and 31 recorded scorers, i.e. FOUR unattributed: 2 in Archangel Michael 0-2 St Anthony, 1 in the Brighton 1-0 St Mark semi-final, 1 for St George in the final.', 'Record four unattributed goals. Do not reproduce the source''s counts.', 'open'),
  ('D5', 'cofta-2025', 'medium', 'Final home/away orientation conflicts within the source.', 'Two places render it ''Archangel Michael, Golders Green 0-1 Anba Abraam, Brighton''; one renders it ''Anba Abraam, Brighton 1-0 Archangel Michael, Golders Green''. Result is identical either way.', 'Majority orientation stored (Golders Green home). Flag for confirmation.', 'open'),
  ('D6', 'cofta-2025', 'medium', 'Three Group B matches display goals with no team attribution.', 'B-R1 Brighton 2-1 St Mark (3 goals: Demas Ramsis, Steven Sava, Sydney Noulton); B-R3 Brighton 2-1 Archangel Michael (Demas Ramsis, Sebastian, Ebi Abdel-Malek); B-R4 Brighton 3-1 St Mark (Stefano, Stavros Akriviadis, Abanoub Fakhoury, Leon Lawandi). Which scorer belongs to the losing side is not determinable.', 'Store scorers with team = null and a flag. Do NOT infer from squad history in other editions.', 'open'),
  ('D7', 'conafa-2026', 'low', 'One goal in the dataset did not come from the source app.', 'Nduoma Chilaka in Nottingham 1-0 Rotherham (A-R6-02) was supplied by the tournament organiser. Minute unknown.', 'Store with source = ''organiser_confirmed''.', 'open');