-- ============================================================
-- COFTA 2026 — historical tournament archive (13 editions, 2022-2026)
--
-- The data rows below this schema are GENERATED from tournament_archive.json.
-- Do not hand-edit them; regenerate. Faithful transcription only: null means
-- the source did not say so, and is never rendered as zero. The eight
-- editions marked 'minimal' stay thin — no synthesised fixtures or standings.
--
-- This SUPERSEDES the past_tournaments jsonb table and set_past_tournament()
-- from 0019. That design stored an edition as one opaque blob, which cannot
-- answer the questions History actually asks (this club's record across
-- editions, this player's goals under a canonical name). The archive is
-- relational instead. The old table is dropped below, but only after proving
-- it is empty.
--
-- CRITICAL — snapshot() stays lean: the archive must never ride in the polled
-- snapshot. Every phone fetches that every 5 seconds and the weekend egress
-- budget is sized without 99 matches and 260 events in it. History reads the
-- archive_* tables directly under public-read RLS and caches hard, which is
-- safe because the archive is immutable.
-- ============================================================

-- ── supersede the jsonb design from 0019 ────────────────────
do $$
begin
  if to_regclass('public.past_tournaments') is not null
     and (select count(*) from public.past_tournaments) > 0 then
    raise exception 'past_tournaments holds rows — refusing to drop it';
  end if;
end $$;

drop function if exists public.set_past_tournament(text, text, int, jsonb);
drop table if exists public.past_tournaments;

-- ── schema ──────────────────────────────────────────────────
create table if not exists public.archive_teams (
  id             uuid primary key,
  canonical_name text not null unique,
  short_name     text not null,
  aliases        text[] not null default '{}',
  merge_status   text not null check (merge_status in ('confirmed','probable','open')),
  -- Clubs that still compete point at their live row, so a future crest or
  -- colour upgrade flows into the archive for free.
  live_team_id   text references public.teams(id),
  -- Branding for historical clubs with no live row. Empty today: they render
  -- a deterministic monogram. A real crest lands here later as DATA (file
  -- under web/crests/archive/) with no schema or UI change.
  display        jsonb,
  -- B teams inherit the parent's crest and colours and render a "B" marker.
  parent_club    text
);

create table if not exists public.archive_editions (
  id                text primary key,
  competition       text not null,
  year              int  not null,
  display_name      text not null,
  category          text not null check (category in ('men','women')),
  date_start        date,
  date_end          date,
  venue             text,
  format            text,
  team_count        int,
  match_count       int,
  champion_team_id  uuid references public.archive_teams(id),
  runner_up_team_id uuid references public.archive_teams(id),
  final_summary     text,
  data_confidence   text not null check (data_confidence in ('full','minimal')),
  source            text,
  -- everything the source carried that has no column of its own: known_gaps,
  -- the various *_note fields, tournament_stats, named squads, the thin
  -- editions' `final` block. Nothing from the source is discarded.
  notes             jsonb not null default '{}'::jsonb
);

create table if not exists public.archive_edition_teams (
  edition_id text not null references public.archive_editions(id) on delete cascade,
  team_id    uuid not null references public.archive_teams(id),
  primary key (edition_id, team_id)
);

create table if not exists public.archive_groups (
  id         text primary key,
  edition_id text not null references public.archive_editions(id) on delete cascade,
  name       text not null
);

create table if not exists public.archive_standings (
  group_id   text not null references public.archive_groups(id) on delete cascade,
  position   int  not null,
  team_id    uuid not null references public.archive_teams(id),
  p int, w int, d int, l int, gf int, ga int, gd int, pts int,
  -- Ark Cup only. Computed by the compiler from the fixture list and NOT
  -- displayed in the source, so they must never be written into gf/ga.
  gf_derived int,
  ga_derived int,
  note text,
  primary key (group_id, position)
);

create table if not exists public.archive_matches (
  id           text primary key,
  edition_id   text not null references public.archive_editions(id) on delete cascade,
  stage        text not null,
  group_name   text,
  round        int,
  label        text,
  match_date   date,
  kickoff_time text,
  pitch        text,
  venue        text,
  home_team_id uuid references public.archive_teams(id),
  away_team_id uuid references public.archive_teams(id),
  home_score   int,
  away_score   int,
  decided_by   text,
  shootout_home int,
  shootout_away int,
  shootout_winner_id uuid references public.archive_teams(id),
  events_status text not null check (events_status in
    ('complete','complete_unattributed','partial','score_only','conflicted')),
  gap_note text,
  notes    jsonb not null default '{}'::jsonb
);

create table if not exists public.archive_players (
  id             uuid primary key,
  canonical_name text not null unique,
  variants       text[] not null default '{}',
  confidence     text,
  rationale      text
);

create table if not exists public.archive_match_events (
  id               bigserial primary key,
  match_id         text not null references public.archive_matches(id) on delete cascade,
  seq              int  not null,
  -- text, not integer: CONAFA 2026 carries '45+1' and most editions carry no
  -- minute at all.
  minute           text,
  -- nullable on purpose: three COFTA 2025 matches display goals with no team
  -- attribution, and guessing was explicitly forbidden.
  team_id          uuid references public.archive_teams(id),
  player_name      text,
  player_canonical text,
  event_type       text not null,
  assist_player    text,
  assist_canonical text,
  event_source     text,
  flag             text,
  note             text
);

create table if not exists public.archive_awards (
  id          bigserial primary key,
  edition_id  text not null references public.archive_editions(id) on delete cascade,
  match_id    text references public.archive_matches(id) on delete cascade,
  award_type  text not null,
  player_name text,
  player_canonical text,
  team_id     uuid references public.archive_teams(id),
  value       int,
  is_published_summary boolean not null default false,
  flag        text
);

create table if not exists public.archive_leaderboards (
  id          bigserial primary key,
  edition_id  text not null references public.archive_editions(id) on delete cascade,
  board_type  text not null,
  rank        int,
  player_name text,
  player_canonical text,
  team_id     uuid references public.archive_teams(id),
  value       int,
  value_source text not null check (value_source in ('published','derived_from_events')),
  -- Where published and derived disagree, this marks the row History leads
  -- with. Both are always stored; nothing is ever discarded.
  is_canonical boolean not null default true,
  flag        text
);

create table if not exists public.archive_conflicts (
  id         text primary key,
  scope      text,
  severity   text,
  issue      text,
  detail     text,
  resolution text,
  status     text not null default 'open'
);

create index if not exists archive_events_match_idx on public.archive_match_events(match_id);
create index if not exists archive_events_canon_idx on public.archive_match_events(player_canonical);
create index if not exists archive_awards_canon_idx on public.archive_awards(player_canonical);
create index if not exists archive_lb_canon_idx     on public.archive_leaderboards(player_canonical);
create index if not exists archive_matches_ed_idx   on public.archive_matches(edition_id);
create index if not exists archive_ed_teams_team_idx on public.archive_edition_teams(team_id);

-- ── RLS: public read, no write path at all ──────────────────
-- The archive is immutable history. Nothing in the app writes it; it changes
-- only by migration, so there is no insert/update/delete policy and no RPC.
do $$
declare t text;
begin
  foreach t in array array['archive_teams','archive_editions','archive_edition_teams',
                           'archive_groups','archive_standings','archive_matches',
                           'archive_players','archive_match_events','archive_awards',
                           'archive_leaderboards','archive_conflicts']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists read_%s on public.%I', t, t);
    execute format('create policy read_%s on public.%I for select using (true)', t, t);
    execute format('grant select on public.%I to anon, authenticated', t);
  end loop;
end $$;

-- ── snapshot(): remove 'history' ────────────────────────────
-- 0019 put a 'history' key in the polled payload. The archive replaces it and
-- must not be polled, so the key goes. Same signature, so grants survive;
-- re-issued at the foot of the file per house style.
create or replace function public.snapshot() returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'now', now(),
    'teams', (select coalesce(jsonb_agg(to_jsonb(t) - 'created_at' order by t.group_letter, t.city), '[]'::jsonb) from public.teams t),
    'players', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', p.id, 'team', p.team_id, 'name', p.name, 'no', p.shirt_no)
        order by p.shirt_no nulls last, p.name), '[]'::jsonb)
      from public.players p where p.active),
    'slots', (select coalesce(jsonb_object_agg(slot, team_id), '{}'::jsonb) from public.slot_overrides),
    'ties', (select coalesce(jsonb_agg(jsonb_build_object(
        'g', ts.group_letter, 'a', ts.team_a, 'b', ts.team_b,
        'sa', ts.score_a, 'sb', ts.score_b)), '[]'::jsonb) from public.tie_shootouts ts),
    'trophies', (select coalesce(jsonb_object_agg(w.trophy, w.players), '{}'::jsonb) from (
        select trophy, jsonb_agg(player_id order by player_id) as players
        from public.trophy_awards group by trophy) w),
    'matches', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', m.id, 'stage', m.stage, 'day', m.day, 'kickoff', m.kickoff, 'pitch', m.pitch,
        'home', m.home_team, 'away', m.away_team, 'hs', m.home_score, 'as', m.away_score,
        'ph', m.pens_home, 'pa', m.pens_away, 'pd', m.pens_decided,
        'ff', m.forfeit_side, 'status', m.status,
        'run', m.clock_running, 'anchor', m.clock_anchor, 'accum', m.clock_accum_ms,
        'v', m.version) order by m.day, m.kickoff, m.pitch), '[]'::jsonb) from public.matches m),
    'events', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', e.id, 'm', e.match_id, 't', e.type, 's', e.side,
        'min', e.minute_label, 'p', e.player_id,
        'a', e.assist_player) order by e.created_at desc), '[]'::jsonb)
      from public.match_events e where not e.voided)
  );
$$;

revoke all on function public.snapshot() from public, anon, authenticated;
grant execute on function public.snapshot() to anon, authenticated;

